interface Account {
  balance: number;
  frozenReason?: string;
}

function withdraw(account: Account | undefined, amount: number): string {
  if (account === undefined) return "no account";
  if (account.frozenReason !== undefined) return `frozen (${account.frozenReason})`;
  if (amount > account.balance) return "insufficient funds";
  return `new balance ${account.balance - amount}`;
}

console.log(withdraw({ balance: 1000 }, 1000));
console.log(withdraw({ balance: 1000, frozenReason: "KYC" }, 10));
console.log(withdraw(undefined, 10));

