function isLarge(amount: number | string): amount is number {
  return typeof amount === "number" && amount > 100000;
}

function describe(amount: number | string): string {
  if (isLarge(amount)) return "review";
  return typeof amount === "string" ? `text ${amount}` : "a number slipped through";
}

console.log(describe(500000), "|", describe("900"), "|", describe(900));

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function deposit(amount: number | null): number {
  assert(amount !== null, "amount is required");
  assert(amount > 0, "amount must be positive");
  return amount * 100;
}

for (const value of [25, null, -5]) {
  try {
    console.log(deposit(value));
  } catch (error) {
    console.log(error instanceof Error ? error.message : "?");
  }
}

