questions.solution:
function toKobo(amount: number | string): number {
  const naira = typeof amount === "string" ? Number(amount.trim()) : amount;
  if (!Number.isFinite(naira) || naira <= 0) return -1;
  return Math.round(naira * 100);
}

console.log(toKobo(25), toKobo(" 12.5 "), toKobo("abc"), toKobo(0), toKobo(-3));

