type Payment =
  | { kind: "card"; amount: number; last4: string }
  | { kind: "transfer"; amount: number; reference: string }
  | { kind: "wallet"; amount: number; phone: string };

function receipt(payment: Payment): string {
  switch (payment.kind) {
    case "card":
      return `card *${payment.last4}: ${payment.amount}`;
    case "transfer":
      return `transfer ${payment.reference}: ${payment.amount}`;
    case "wallet":
      return `wallet ${payment.phone}: ${payment.amount}`;
  }
}

console.log(receipt({ kind: "card", amount: 5000, last4: "4242" }));
console.log(receipt({ kind: "transfer", amount: 12000, reference: "RENT" }));
console.log(receipt({ kind: "wallet", amount: 800, phone: "08031234567" }));

