class InsufficientFundsError extends Error {
  constructor(readonly shortBy: number) {
    super("insufficient funds");
  }
}

function explain(error: unknown): string {
  if (error instanceof InsufficientFundsError) return `top up ${error.shortBy}`;
  if (error instanceof Error) return `failed: ${error.message}`;
  return `failed: ${String(error)}`;
}

console.log(explain(new InsufficientFundsError(2500)));
console.log(explain(new RangeError("amount too large")));
console.log(explain("timeout"));

